CREATE TABLE rental_contacts (id TEXT PRIMARY KEY, landlord_id TEXT NOT NULL REFERENCES users(id), condominium_id TEXT NOT NULL REFERENCES condominiums(id), name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rentals (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), lot_id TEXT NOT NULL REFERENCES lots(id), landlord_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('lease','booking')), title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','active','ended','cancelled','confirmed','completed')), starts_on TEXT NOT NULL, ends_on TEXT, payload TEXT NOT NULL CHECK(json_valid(payload)), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX rentals_lot_dates ON rentals(lot_id,starts_on,ends_on);
CREATE TABLE rental_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, rental_id TEXT NOT NULL, actor_id TEXT NOT NULL, version INTEGER NOT NULL, snapshot TEXT NOT NULL, happened_at TEXT NOT NULL);
CREATE TRIGGER rental_create_overlap BEFORE INSERT ON rentals WHEN NEW.status IN ('active','ended','confirmed','completed') BEGIN SELECT RAISE(ABORT,'RENTAL_OVERLAP') WHERE EXISTS (SELECT 1 FROM rentals r WHERE r.lot_id=NEW.lot_id AND r.status IN ('active','ended','confirmed','completed') AND r.starts_on<COALESCE(NEW.ends_on,'9999-12-31') AND COALESCE(r.ends_on,'9999-12-31')>NEW.starts_on); END;
CREATE TRIGGER rental_update_overlap BEFORE UPDATE ON rentals WHEN NEW.status IN ('active','ended','confirmed','completed') BEGIN SELECT RAISE(ABORT,'RENTAL_OVERLAP') WHERE EXISTS (SELECT 1 FROM rentals r WHERE r.id!=NEW.id AND r.lot_id=NEW.lot_id AND r.status IN ('active','ended','confirmed','completed') AND r.starts_on<COALESCE(NEW.ends_on,'9999-12-31') AND COALESCE(r.ends_on,'9999-12-31')>NEW.starts_on); END;
CREATE TRIGGER rental_updated BEFORE UPDATE ON rentals BEGIN INSERT INTO rental_revisions(rental_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,NEW.landlord_id,OLD.version,json_object('title',OLD.title,'status',OLD.status,'startsOn',OLD.starts_on,'endsOn',OLD.ends_on,'payload',json(OLD.payload)),NEW.updated_at); END;
